#include "list.h"
#include <pthread.h>
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"LIST_THREAD_CHECK:%d:%s\n",__LINE__,#x);abort();}}while(0)
typedef struct {SxList list;SxParticipant p[2];atomic_uint ready,release,start;unsigned mode;} Case;
static int enter(Case*c,unsigned p){int rc;do{rc=sx_enter(&c->list,c->p[p]);if(rc==MB_BUSY)sched_yield();}while(rc==MB_BUSY);return rc;}
static int leave(Case*c,unsigned p){int rc;do{rc=sx_leave(&c->list,c->p[p]);if(rc==MB_BUSY)sched_yield();}while(rc==MB_BUSY);return rc;}
static void *paused(void*arg){Case*c=arg;SxObserved o;SxProtected p;unsigned v=999;CHECK(enter(c,0)==MB_OK);CHECK(sx_observe(&c->list,c->p[0],0,&o)==MB_OK);CHECK(sx_protect(&c->list,c->p[0],0,o,&p)==MB_OK);atomic_store_explicit(&c->ready,1,memory_order_release);while(!atomic_load_explicit(&c->release,memory_order_acquire))sched_yield();CHECK(sx_read(&c->list,c->p[0],p,&v)==MB_OK&&v==11);CHECK(leave(c,0)==MB_OK);return NULL;}
static void *reader(void*arg){Case*c=arg;while(!atomic_load_explicit(&c->start,memory_order_acquire))sched_yield();for(unsigned i=0;i<200;i++){SxObserved o;SxProtected p;unsigned v=999;int rc;CHECK(enter(c,1)==MB_OK);do{rc=sx_observe(&c->list,c->p[1],0,&o);}while(rc==MB_BUSY);CHECK(rc==MB_OK||rc==MB_EMPTY);if(rc==MB_OK){do{rc=sx_protect(&c->list,c->p[1],0,o,&p);}while(rc==MB_BUSY);CHECK(rc==MB_OK||rc==MB_RETRY);if(rc==MB_OK){do{rc=sx_read(&c->list,c->p[1],p,&v);}while(rc==MB_BUSY);CHECK(rc==MB_OK&&(v==11||v==22||v==33));}}CHECK(leave(c,1)==MB_OK);}return NULL;}
int main(void){unsigned retained[2]={0,0};for(unsigned mode=0;mode<2;mode++)for(unsigned round=0;round<30;round++){Case c;pthread_t a,b;unsigned value,count;int rc;CHECK(sx_list_init(&c.list,mode)==MB_OK);c.mode=mode;atomic_init(&c.ready,0);atomic_init(&c.release,0);atomic_init(&c.start,0);for(unsigned p=0;p<2;p++)CHECK(sx_register(&c.list,&c.p[p])==MB_OK);for(unsigned i=1;i<=3;i++)CHECK(sx_append(&c.list,11*i)==MB_OK);CHECK(pthread_create(&a,NULL,paused,&c)==0);while(!atomic_load_explicit(&c.ready,memory_order_acquire))sched_yield();CHECK(pthread_create(&b,NULL,reader,&c)==0);atomic_store_explicit(&c.start,1,memory_order_release);for(unsigned i=1;i<=3;i++){do{rc=sx_remove(&c.list,&value);}while(rc==MB_BUSY);CHECK(rc==MB_OK&&value==11*i);}CHECK(pthread_join(b,NULL)==0);if(mode==SX_EPOCH)CHECK(sx_advance(&c.list)==MB_OK&&sx_advance(&c.list)==MB_BUSY);CHECK(sx_collect(&c.list,&count)==MB_OK&&count==(mode==SX_HAZARD?2u:0u));retained[mode]+=3-count;CHECK(sx_depart(&c.list,c.p[0])==MB_BUSY);atomic_store_explicit(&c.release,1,memory_order_release);CHECK(pthread_join(a,NULL)==0);if(mode==SX_EPOCH)CHECK(sx_advance(&c.list)==MB_OK);CHECK(sx_collect(&c.list,&count)==MB_OK&&count==(mode==SX_HAZARD?1u:3u));for(unsigned p=0;p<2;p++)CHECK(sx_depart(&c.list,c.p[p])==MB_OK);}
 CHECK(retained[0]==30&&retained[1]==90);puts("LIST_THREAD_PASS rounds=60 pool=3 paused_hazard=1 paused_epoch=3 joined_before_depart=1");return 0;}
